// Env is generated by `wrangler types`; no privileged Supabase key belongs here.
/// <reference path="./worker-configuration.d.ts" />
export type Assets=Record<string,{data:string;type:string;cache:string}>;
type Session={access_token:string;refresh_token:string;expires_in:number};
const cookieName='__Host-fodo-session',deviceName='__Host-fodo-device';
const allowed=new Set(['bootstrap','reports','commands','setup','openings','receipts','kitchen-issues','purchases','transfers','counts','recipes','production','menu','sales','finance']);
const json=(body:unknown,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
const error=(status:number,message:string)=>json({code:status===401?'AUTH_REQUIRED':'REQUEST_REJECTED',message},status);
function cookie(request:Request,name:string){return (request.headers.get('Cookie')??'').split(';').map(s=>s.trim()).find(s=>s.startsWith(name+'='))?.slice(name.length+1)??'';}
function readTokens(request:Request):Session|null{try{const s=JSON.parse(atob(cookie(request,cookieName))) as Session;if(!/^[A-Za-z0-9_.-]+$/.test(s.access_token)||!/^[A-Za-z0-9_.-]+$/.test(s.refresh_token))return null;return s;}catch{return null;}}
function sessionCookies(response:Response,session:Session,device?:string){
 response.headers.append('Set-Cookie',`${cookieName}=${btoa(JSON.stringify(session))}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=604800`);
 if(device)response.headers.append('Set-Cookie',`${deviceName}=${device}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=604800`);
 return response;
}
async function auth(env:Env,grant:string,body:unknown){return fetch(env.SUPABASE_URL+'/auth/v1/token?grant_type='+grant,{method:'POST',headers:{apikey:env.SUPABASE_PUBLISHABLE_KEY,'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});}
async function backend(env:Env,path:string,session:Session,device:string,request?:Request,body?:string){
 return fetch(env.SUPABASE_URL+'/functions/v1/fodo-api/'+path,{method:request?.method??'GET',headers:{apikey:env.SUPABASE_PUBLISHABLE_KEY,Authorization:'Bearer '+session.access_token,'X-Fodo-Device':device,'Content-Type':'application/json','X-Fodo-Generation':request?.headers.get('X-Fodo-Generation')??''},body,signal:AbortSignal.timeout(25000)});
}
export async function handle(request:Request,env:Env,assets:Assets,buildId:string):Promise<Response>{
 const url=new URL(request.url),path=url.pathname;
 if(request.method!=='GET'&&request.method!=='HEAD'){
  if(request.headers.get('Origin')!==url.origin)return error(403,'مصدر الطلب غير مسموح.');
  if(Number(request.headers.get('Content-Length')??0)>1024*1024)return error(413,'الطلب يتجاوز الحد المسموح.');
 }
 if(path==='/api/v1/health'&&request.method==='GET')return json({service:'fodo',buildVersion:buildId,mode:'hosted',salesStockPolicy:'selected_available_stock',salesShortagePolicy:'accept_and_highlight'});
 if(path==='/api/v1/auth/login'&&request.method==='POST'){
  const text=await request.text();if(text.length>2048)return error(413,'الطلب يتجاوز الحد المسموح.');
  let body:{email:string;password:string;deviceId:string};try{body=JSON.parse(text);}catch{return error(400,'بيانات الطلب غير صالحة.');}
  if(typeof body.email!=='string'||body.email.length>254||typeof body.password!=='string'||body.password.length>100||!/^\w{8}-(\w{4}-){3}\w{12}$/.test(body.deviceId??''))return error(400,'تحقق من بيانات الدخول.');
  const r=await auth(env,'password',{email:body.email,password:body.password});if(!r.ok){await r.body?.cancel();return error(r.status===429?429:r.status>=500?503:401,'تعذر تسجيل الدخول.');}
  const session=await r.json() as Session;
  const scoped=await backend(env,'bootstrap',session,body.deviceId);if(!scoped.ok){await scoped.body?.cancel();return error(scoped.status>=500||scoped.status===429?503:scoped.status===401?401:403,'تعذر فتح مساحة العمل.');}
  // Discard the verification snapshot; it is downloaded through the standard bootstrap path.
  await scoped.arrayBuffer();return sessionCookies(json({ok:true}),session,body.deviceId);
 }
 if(path==='/api/v1/auth/logout'&&request.method==='POST'){
  const session=readTokens(request);if(session)await fetch(env.SUPABASE_URL+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:env.SUPABASE_PUBLISHABLE_KEY,Authorization:'Bearer '+session.access_token},signal:AbortSignal.timeout(10000)});
  const r=json({ok:true});for(const name of [cookieName,deviceName])r.headers.append('Set-Cookie',`${name}=; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=0`);return r;
 }
 if(path.startsWith('/api/')){
  const route=path.slice('/api/v1/'.length);if(!path.startsWith('/api/v1/')||!allowed.has(route)||request.method!==(route==='bootstrap'?'GET':'POST'))return error(404,'المسار غير متاح.');
  let session=readTokens(request);if(!session)return error(401,'سجّل الدخول للمزامنة.');
  const device=cookie(request,deviceName);const body=request.method==='POST'?await request.text():undefined;
  if(body&&new TextEncoder().encode(body).length>1024*1024)return error(413,'الطلب يتجاوز الحد المسموح.');
  let r=await backend(env,route,session,device,request,body),renewed=false;
  if(r.status===401){await r.arrayBuffer();const refreshed=await auth(env,'refresh_token',{refresh_token:session.refresh_token});if(!refreshed.ok)return error(401,'انتهت الجلسة. سجّل الدخول مجدداً.');session=await refreshed.json() as Session;renewed=true;r=await backend(env,route,session,device,request,body);}
  const response=new Response(r.body,{status:r.status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'}});
  return renewed?sessionCookies(response,session):response;
 }
 if(!['GET','HEAD'].includes(request.method))return error(405,'الطلب غير متاح.');
 const asset=assets[path];if(!asset)return error(404,'الصفحة غير متاحة.');
 const bytes=Uint8Array.from(atob(asset.data),c=>c.charCodeAt(0));
 let body:BodyInit=bytes;const headers=new Headers({'Content-Type':asset.type,'Cache-Control':asset.cache,'Vary':'Accept-Encoding'});
 if(request.headers.get('Accept-Encoding')?.includes('gzip'))headers.set('Content-Encoding','gzip');else body=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
 if(path==='/sw.js')headers.set('Service-Worker-Allowed','/');
 // These bytes are already gzip encoded. Cloudflare must not encode them again.
 return new Response(request.method==='HEAD'?null:body,{headers,encodeBody:'manual'} as ResponseInit & {encodeBody:'manual'});
}
export function createWorker(assets:Assets,buildId:string){return {async fetch(request:Request,env:Env){
 let r:Response;try{r=await handle(request,env,assets,buildId);}catch{r=error(503,'تعذر الاتصال بالخدمة. حاول مجدداً.');}
 r.headers.set('X-Content-Type-Options','nosniff');r.headers.set('Referrer-Policy','same-origin');r.headers.set('X-Frame-Options','DENY');
 r.headers.set('Permissions-Policy','camera=(), microphone=(), geolocation=()');
 r.headers.set('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'; connect-src 'self' http://127.0.0.1:17856; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");
 r.headers.set('Strict-Transport-Security','max-age=31536000');return r;
}};}
